const paths={home:"M3 11.5 12 4l9 7.5V21h-6v-6H9v6H3v-9.5Z",user:"M20 21a8 8 0 0 0-16 0M12 13a5 5 0 1 0 0-10 5 5 0 0 0 0 10Z",film:"M3 5h18v14H3zM7 5v14M17 5v14M3 9h4M17 9h4M3 15h4M17 15h4",layers:"m12 2 9 5-9 5-9-5 9-5Zm-9 10 9 5 9-5M3 17l9 5 9-5",edit:"M12 20h9M16.5 3.5a2.1 2.1 0 0 1 3 3L8 18l-4 1 1-4L16.5 3.5Z",timeline:"M3 7h10v4H3zM7 15h14v4H7zM16 5v8",tasks:"M9 6h11M9 12h11M9 18h11M4 6h.01M4 12h.01M4 18h.01",send:"m22 2-7 20-4-9-9-4 20-7ZM22 2 11 13",settings:"M12 15.5a3.5 3.5 0 1 0 0-7 3.5 3.5 0 0 0 0 7ZM19 15l2 2-4 4-2-2M9 20H5v-4M5 8V4h4M15 4h4v4",search:"m21 21-4.35-4.35M19 11a8 8 0 1 1-16 0 8 8 0 0 1 16 0Z",plus:"M12 5v14M5 12h14",play:"m8 5 11 7-11 7V5Z",pause:"M9 5v14M15 5v14",more:"M5 12h.01M12 12h.01M19 12h.01",chevron:"m9 18 6-6-6-6",back:"m15 18-6-6 6-6",check:"m5 12 4 4L19 6",clock:"M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20ZM12 6v6l4 2",folder:"M3 6h7l2 2h9v11H3z",waveform:"M4 12h2l2-6 3 12 3-9 2 6 2-3h2",caption:"M4 5h16v14H4zM8 10h3M8 14h3M14 10h2M14 14h2",music:"M9 18V5l10-2v13M9 9l10-2M6 21a3 3 0 1 0 0-6 3 3 0 0 0 0 6ZM16 19a3 3 0 1 0 0-6 3 3 0 0 0 0 6Z",magic:"m12 3 1.4 5.1L19 10l-5.1 1.4L12 17l-1.4-5.6L5 10l5.6-1.9L12 3ZM19 17l.6 2.4L22 20l-2.4.6L19 23l-.6-2.4L16 20l2.4-.6L19 17Z",grid:"M4 4h6v6H4zM14 4h6v6h-6zM4 14h6v6H4zM14 14h6v6h-6z",filter:"M4 5h16M7 12h10M10 19h4",bell:"M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9ZM10 21h4",replace:"M20 7h-7M17 3l4 4-4 4M4 17h7M7 21l-4-4 4-4",trash:"M4 7h16M9 7V4h6v3M7 7l1 14h8l1-14"};
function Icon({name,size=18}){return <svg viewBox="0 0 24 24" width={size} height={size} fill="none" stroke="currentColor" strokeWidth="1.65" strokeLinecap="round" strokeLinejoin="round"><path d={paths[name]||paths.grid}/></svg>}
const nav=[["\u5de5\u4f5c\u53f0","home"],["\u8d26\u53f7\u6863\u6848","user"],["\u7d20\u6750\u4e2d\u5fc3","film"],["\u955c\u5934\u526a\u8f91","edit"],["\u65f6\u95f4\u8f74","timeline"],["\u6279\u91cf\u751f\u6210","grid"],["\u4efb\u52a1\u4e2d\u5fc3","tasks"],["\u53d1\u5e03\u4e2d\u5fc3","send"]];
const Button=({children,primary=false,icon,quiet=false,onClick,className="",disabled=false})=><button disabled={disabled} onClick={onClick} className={`button ${primary?"primary":""} ${quiet?"quiet":""} ${className}`}>{icon&&<Icon name={icon} size={16}/>}<span>{children}</span></button>;
const Pill=({children,tone=""})=><span className={`pill ${tone}`}>{children}</span>;
function decodeUnicodeText(value){if(typeof value!=="string"||!value.includes("\\u"))return value;return value.replace(/\\u([0-9a-fA-F]{4})/g,(_,hex)=>String.fromCharCode(parseInt(hex,16)))}
function decodePayload(value){if(Array.isArray(value))return value.map(decodePayload);if(value&&typeof value==="object")return Object.fromEntries(Object.entries(value).map(([key,item])=>[key,decodePayload(item)]));return decodeUnicodeText(value)}
async function request(path,options={}){const res=await fetch(path,{headers:{"Content-Type":"application/json"},...options,body:options.body&&typeof options.body!=="string"?JSON.stringify(options.body):options.body});const json=await res.json();if(!json.ok)throw Error(decodeUnicodeText(json.error)||"操作失败");return decodePayload(json.data)}
const empty={profiles:[],categories:[],materials:[],templates:[],shots:[],tasks:[],batch_tasks:[],batch_items:[],bgms:[],transitions:[],sound_effects:[],ai_services:[],tts_services:[],tts_voices:[],platforms:[],publish_accounts:[],publish_tasks:[],publish_channels:[],platform_test_runs:[],admin_mode:false,settings:{}};
function timeText(v){const n=Number(v||0);return `${Math.floor(n/60).toString().padStart(2,"0")}:${Math.floor(n%60).toString().padStart(2,"0")}`}

function Rail({page,setPage,tasks}){return <aside className="rail"><button className="logo" onClick={()=>setPage("工作台")}><img src="/brand-mark.svg"/><span><b>MIXCUT</b><small>STUDIO</small></span></button><nav>{nav.map(([label,icon])=><button key={label} className={page===label?"active":""} onClick={()=>setPage(label)}><Icon name={icon}/><span>{label}</span>{label==="任务中心"&&tasks>0&&<em>{tasks}</em>}</button>)}</nav><div className="rail-bottom"><button className={page==="设置"?"active":""} onClick={()=>setPage("设置")}><Icon name="settings"/><span>系统设置</span></button><div className="login-state"><i/><div><b>本地工作站</b><small>SQLite 已连接</small></div></div></div></aside>}
function Topbar({db}){const active=(db.tasks||[]).filter(t=>["running","processing_shot","merging","pending","queued"].includes(t.status)).length;const dbName=(db.db_path||"mixcut.db").split(/[\\/]/).pop();return <header className="topbar"><div className="product-title"><span>PROJECT</span><b>{db.templates.length?db.templates[0].name:"未命名项目"}</b></div><div className="studio-stats"><div><span>DATABASE</span><b>{dbName}</b></div><div><span>MEDIA</span><b>{db.materials.length}</b></div><div><span>TASKS</span><b>{active}</b></div></div><div className="global-actions"><div className="engine-state"><i/><span>ENGINE READY</span></div><div className="user-chip"><b>LOCAL</b><small>v1.3.6</small></div></div></header>}
function PageHeader({kicker,title,desc,children}){return <header className="page-header"><div><span>{kicker}</span><h1>{title}</h1><p>{desc}</p></div><div>{children}</div></header>}

function AssetsPage({db,refresh,notify}){const [cat,setCat]=useState("全部");const [query,setQuery]=useState("");const [busy,setBusy]=useState(false);const filtered=useMemo(()=>db.materials.filter(m=>(cat==="全部"||m.category_name===cat)&&m.file_name.toLowerCase().includes(query.toLowerCase())),[db,cat,query]);const scan=async()=>{try{setBusy(true);const f=await request("/api/select-folder",{method:"POST",body:{}});if(!f.path)return;const r=await request("/api/materials/scan",{method:"POST",body:{folder_path:f.path}});notify(`扫描完成：新增 ${r.added}，更新 ${r.updated}`);await refresh()}finally{setBusy(false)}};const setCategory=async(id,category_id)=>{await request("/api/materials/category",{method:"POST",body:{material_id:id,category_id}});notify("素材分类已更新");refresh(false)};return <div className="page assets-page"><PageHeader kicker={`MEDIA / ${db.materials.length} ITEMS`} title="素材中心" desc="数据来自本地 materials 表，缩略图和时长均为真实文件。"><Button primary icon="folder" disabled={busy} onClick={scan}>{busy?"正在扫描":"扫描文件夹"}</Button></PageHeader><div className="library-bar"><div className="search-box"><Icon name="search"/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="搜索素材"/></div><div className="category-tabs"><button className={cat==="全部"?"active":""} onClick={()=>setCat("全部")}>全部</button>{db.categories.map(c=><button className={cat===c.name?"active":""} onClick={()=>setCat(c.name)} key={c.id}>{c.name}</button>)}</div></div><div className="library-summary"><span>显示 <b>{filtered.length}</b> 个真实素材</span><span>按最近扫描排序</span></div><div className="asset-grid">{filtered.map((a,i)=><article key={a.id}><div className="asset-preview" style={{backgroundImage:`linear-gradient(180deg,transparent 55%,rgba(5,7,8,.65)),url(${a.thumbnail_url})`}}><span className="asset-order">{String(i+1).padStart(2,"0")}</span><span className="asset-size">{a.width}×{a.height}</span><i><Icon name="play"/></i><b>{timeText(a.duration)}</b></div><div className="asset-info"><div><strong>{a.file_name}</strong></div><select value={a.category_id||""} onChange={e=>setCategory(a.id,Number(e.target.value))}>{db.categories.map(c=><option value={c.id} key={c.id}>{c.name}</option>)}</select><small>{(a.size/1024/1024).toFixed(1)} MB</small></div></article>)}</div></div>}

function ShotCard({shot,categories,voices,profileId,refresh,notify}){const [form,setForm]=useState(shot);useEffect(()=>setForm(shot),[shot]);const save=async patch=>{const next={...form,...patch};setForm(next);await request("/api/shots",{method:"POST",body:next});refresh(false)};const action=async(kind,body={})=>{const r=await request(`/api/shots/${shot.id}/${kind}`,{method:"POST",body});const msg=kind==="tts"?`语音已生成：${r.voice_duration.toFixed(1)} 秒`:kind==="rewrite"?"AI 改写已完成":`已匹配：${r.file_name}`;notify(msg);refresh()};const move=async direction=>{await request(`/api/shots/${shot.id}/move`,{method:"POST",body:{direction}});refresh()};const remove=async()=>{if(!confirm("确定删除这个镜头？"))return;await request(`/api/shots/${shot.id}`,{method:"DELETE"});notify("镜头已删除");refresh()};return <article className="active"><div className="simple-shot-top"><span>镜头 {shot.sort_order}</span><input value={form.shot_name||""} onChange={e=>setForm({...form,shot_name:e.target.value})} onBlur={()=>save({})}/><button className="shot-icon" onClick={()=>move(-1)}>↑</button><button className="shot-icon" onClick={()=>move(1)}>↓</button><Button quiet onClick={()=>action("rewrite",{profile_id:profileId})}>改写</Button><Button quiet onClick={()=>action("tts")}>语音</Button><Button quiet onClick={()=>action("match")}>素材</Button><button className="shot-icon danger" onClick={remove}><Icon name="trash" size={14}/></button></div><div className="simple-copy-row"><label>模板原句<textarea value={form.original_text||""} onChange={e=>setForm({...form,original_text:e.target.value})} onBlur={()=>save({})}/></label><label>改写文案<textarea placeholder="点击“改写”后生成" value={form.ai_text||""} onChange={e=>setForm({...form,ai_text:e.target.value})} onBlur={()=>save({})}/></label></div><div className="simple-shot-meta"><label>素材类别<select value={form.material_category_id||""} onChange={e=>save({material_category_id:Number(e.target.value)})}><option value="">选择类别</option>{categories.map(c=><option value={c.id} key={c.id}>{c.name}</option>)}</select></label><label className="simple-toggle">静音<button onClick={()=>save({mute_original_audio:!form.mute_original_audio})} className={`switch ${form.mute_original_audio?"on":""}`}><i/></button></label><label className="simple-toggle">字幕<button onClick={()=>save({enable_subtitle:!form.enable_subtitle})} className={`switch ${form.enable_subtitle?"on":""}`}><i/></button></label></div></article>}

function NumberControl({value,onChange,min=0,max=999,step=1}){const number=Number(value||0);const apply=n=>onChange(String(Math.max(min,Math.min(max,Number(n)||0))));return <div className="number-control"><button type="button" onClick={()=>apply(number-step)}>{"\u2212"}</button><input type="number" min={min} max={max} step={step} value={value} onChange={e=>apply(e.target.value)}/><button type="button" onClick={()=>apply(number+step)}>{"\uFF0B"}</button></div>}
function SettingBlock({title,children}){return <section className="modal-setting-block"><h3>{title}</h3><div>{children}</div></section>}
function TitleSubtitleModal({settings,onClose,onSaved,notify}){const[tab,setTab]=useState("title");const styleKeys=["title_font_dir","title_font","title_font_size","title_color","title_auto_fit","title_background_enabled","title_background_color","title_background_opacity","title_background_padding_y","title_center","title_outline_width","title_outline_color","title_shadow_color","title_shadow_x","title_shadow_y","title_main_x","title_main_y","title_sub_x","title_sub_y","subtitle_enabled","subtitle_font","subtitle_font_size","subtitle_color","subtitle_outline_width","subtitle_outline_color","subtitle_margin_bottom","subtitle_max_chars_per_line","subtitle_effect","subtitle_effect_duration"];const readPreset=name=>({...settings,...Object.fromEntries(styleKeys.map(key=>[key,settings[`${name}_${key}`]??settings[key]]))});const initialPreset=settings.title_style_preset||"domestic";const[preset,setPreset]=useState(initialPreset);const[presetForms,setPresetForms]=useState(()=>({domestic:readPreset("domestic"),international:readPreset("international")}));const[form,setForm]=useState(()=>readPreset(initialPreset));const[renderedPreview,setRenderedPreview]=useState("");const fontOptions=[{value:"Microsoft YaHei",label:"微软雅黑"},{value:"Smiley Sans Oblique",label:"得意黑（推荐）"},{value:"WDXL Lubrifont SC",label:"滑油字（推荐）"},{value:"ZCOOL QingKe HuangYou",label:"站酷庆科黄油体"},{value:"ZCOOL KuaiLe",label:"站酷快乐体"},{value:"ZCOOL XiaoWei",label:"站酷小薇体"},{value:"LXGW WenKai GB Screen",label:"霞鹜文楷"},{value:"Ma Shan Zheng",label:"马善政毛笔体"},{value:"Long Cang",label:"龙藏体"},{value:"SimHei",label:"黑体"},{value:"Arial",label:"Arial"}];useEffect(()=>{if(tab!=="title")return;let active=true;const timer=setTimeout(()=>{request("/api/title-preview",{method:"POST",body:form}).then(r=>{if(active)setRenderedPreview(r.url)}).catch(()=>{})},260);return()=>{active=false;clearTimeout(timer)}},[tab,form]);const set=(key,value)=>setForm(v=>({...v,[key]:value}));const switchPreset=next=>{if(next===preset)return;const all={...presetForms,[preset]:form};setPresetForms(all);setPreset(next);setForm(all[next]||readPreset(next))};const save=async()=>{const all={...presetForms,[preset]:form};const stored={};Object.entries(all).forEach(([name,values])=>styleKeys.forEach(key=>stored[`${name}_${key}`]=values[key]??""));const payload={...form,...stored,title_style_preset:preset};const value=await request("/api/settings",{method:"POST",body:payload});onSaved(value);notify(`${preset==="domestic"?"国内":"国外"}标题与字幕模板已保存并启用`);onClose()};const chooseFont=async()=>{const r=await request("/api/select-folder",{method:"POST",body:{}});if(r.path)set("title_font_dir",r.path)};const titleMain=form.title_main||"主标题样式预览";const titleSub=form.title_sub||"";const textWidth=value=>Array.from(value||"").reduce((sum,ch)=>sum+(ch.charCodeAt(0)>255?1:.58),0);const previewScale=295/1080;const titleFontSize=Number(form.title_font_size||118);const previewTitleSize=Math.max(5,titleFontSize*previewScale);const titleScale=value=>String(form.title_auto_fit||"0")==="1"?Math.max(.25,Math.min(1,(1080*.9)/Math.max(1,textWidth(value)*titleFontSize))):1;const titleLineStyle=(value,prefix)=>({left:`${Number(form[`${prefix}_x`]||50)}%`,top:`${Number(form[`${prefix}_y`]||0)}%`,transform:`translate(-50%,-50%) scaleX(${titleScale(value)})`,transformOrigin:"center"});const dragTitle=(prefix,e)=>{if(!(e.buttons&1))return;const rect=e.currentTarget.parentElement.getBoundingClientRect();const x=Math.max(3,Math.min(97,(e.clientX-rect.left)/rect.width*100));const y=Math.max(3,Math.min(82,(e.clientY-rect.top)/rect.height*100));setForm(v=>({...v,[`${prefix}_x`]:x.toFixed(1),[`${prefix}_y`]:y.toFixed(1),title_center:"0"}))};const titleStyle={fontFamily:form.title_font||"Microsoft YaHei",fontSize:`${previewTitleSize}px`,color:form.title_color||"#FFE67A",WebkitTextStroke:`${Math.max(0,Number(form.title_outline_width||1)*previewScale)}px ${form.title_outline_color||"#000"}`,textShadow:`${Number(form.title_shadow_x||2)*previewScale}px ${Number(form.title_shadow_y||2)*previewScale}px 0 ${form.title_shadow_color||"#F15A24"}`,textAlign:String(form.title_center||"1")==="1"?"center":"left"};const subtitleStyle={fontFamily:form.subtitle_font||"Microsoft YaHei",fontSize:`${Math.max(8,Number(form.subtitle_font_size||78)*previewScale)}px`,color:form.subtitle_color||"#fff",WebkitTextStroke:`${Math.max(0,Number(form.subtitle_outline_width||1)*previewScale)}px ${form.subtitle_outline_color||"#000"}`,bottom:`${Math.min(62.5,Math.max(0,Number(form.subtitle_margin_bottom||446)/1920*100))}%`};const subtitleLimit=Math.max(6,Math.min(30,Number(form.subtitle_max_chars_per_line||14)));const subtitlePreviewRaw="第一行尽量显示更长接近画面边缘才自动换行";const subtitlePreviewChars=Array.from(subtitlePreviewRaw);const subtitlePreviewText=Array.from({length:Math.ceil(subtitlePreviewChars.length/subtitleLimit)},(_,i)=>subtitlePreviewChars.slice(i*subtitleLimit,(i+1)*subtitleLimit).join("")).join("\n");
return <div className="title-modal-mask" onMouseDown={e=>e.target===e.currentTarget&&onClose()}><div className="title-modal"><header><h2>顶部标题及字幕设置</h2><button type="button" onClick={onClose}>{"\u00D7"}</button></header><div className="title-modal-body"><div className="title-modal-editor"><div className="style-preset-switch"><b>{"样式模板"}</b><button type="button" className={preset==="domestic"?"active":""} onClick={()=>switchPreset("domestic")}>{"国内模板"}</button><button type="button" className={preset==="international"?"active":""} onClick={()=>switchPreset("international")}>{"国外模板"}</button><span>{"当前生成视频使用此模板"}</span></div><nav><button className={tab==="title"?"active":""} onClick={()=>setTab("title")}>顶部标题</button><button className={tab==="subtitle"?"active":""} onClick={()=>setTab("subtitle")}>字幕显示</button></nav>{tab==="title"?<div className="modal-tab-content"><SettingBlock title="基础信息"><label><span>主标题</span><input placeholder="请输入主标题" value={form.title_main||""} onChange={e=>set("title_main",e.target.value)}/></label><label><span>副标题</span><input placeholder="可选；填写后成片显示副标题" value={form.title_sub||""} onChange={e=>set("title_sub",e.target.value)}/></label></SettingBlock><SettingBlock title="字体与样式"><div className="font-folder-row"><span>字体目录</span><input readOnly value={form.title_font_dir||"默认字体文件夹"}/><Button quiet onClick={chooseFont}>选择本地字体文件夹</Button></div><div className="modal-grid"><label><span>字体</span><select value={form.title_font||"Microsoft YaHei"} onChange={e=>set("title_font",e.target.value)}>{fontOptions.map(font=><option value={font.value} key={font.value}>{font.label}</option>)}</select></label><label><span>字号</span><NumberControl value={form.title_font_size||"118"} onChange={v=>set("title_font_size",v)} min={20} max={240}/></label><label><span>字体颜色</span><input type="color" value={form.title_color||"#FFE67A"} onChange={e=>set("title_color",e.target.value)}/></label><label className="modal-toggle"><span>标题底色</span><button type="button" onClick={()=>set("title_background_enabled",String(form.title_background_enabled||"0")==="1"?"0":"1")} className={`switch ${String(form.title_background_enabled||"0")==="1"?"on":""}`}><i/></button></label><label><span>底色颜色</span><input type="color" value={form.title_background_color||"#16B8B8"} onChange={e=>set("title_background_color",e.target.value)}/></label><label><span>底色透明度</span><NumberControl value={form.title_background_opacity||"72"} onChange={v=>set("title_background_opacity",v)} min={0} max={100} step={5}/></label><label><span>底色上下留白</span><NumberControl value={form.title_background_padding_y||"22"} onChange={v=>set("title_background_padding_y",v)} min={0} max={120} step={2}/></label><label className="modal-toggle"><span>自动适应宽度</span><button type="button" onClick={()=>set("title_auto_fit",String(form.title_auto_fit||"0")==="1"?"0":"1")} className={`switch ${String(form.title_auto_fit||"0")==="1"?"on":""}`}><i/></button></label><label className="modal-toggle"><span>居中</span><button type="button" onClick={()=>{const centered=String(form.title_center||"1")!=="1";setForm(v=>({...v,title_center:centered?"1":"0",...(centered?{title_main_x:"50",title_sub_x:"50"}:{})}))}} className={`switch ${String(form.title_center||"1")==="1"?"on":""}`}><i/></button></label><label><span>描边宽度</span><NumberControl value={form.title_outline_width||"1"} onChange={v=>set("title_outline_width",v)} min={0} max={12}/></label><label><span>描边颜色</span><input type="color" value={form.title_outline_color||"#000000"} onChange={e=>set("title_outline_color",e.target.value)}/></label><label><span>阴影颜色</span><input type="color" value={form.title_shadow_color||"#F15A24"} onChange={e=>set("title_shadow_color",e.target.value)}/></label><label><span>阴影 X 偏移</span><NumberControl value={form.title_shadow_x||"2"} onChange={v=>set("title_shadow_x",v)} min={-200} max={200}/></label><label><span>阴影 Y 偏移</span><NumberControl value={form.title_shadow_y||"2"} onChange={v=>set("title_shadow_y",v)} min={-200} max={200}/></label></div></SettingBlock></div>:<div className="modal-tab-content"><div className="subtitle-master"><div><b>字幕显示</b><p>智能配音时在视频中显示字幕</p></div><button type="button" onClick={()=>set("subtitle_enabled",String(form.subtitle_enabled||"1")==="1"?"0":"1")} className={`switch ${String(form.subtitle_enabled||"1")==="1"?"on":""}`}><i/></button></div><SettingBlock title="基础设置"><div className="modal-grid"><label><span>字号</span><NumberControl value={form.subtitle_font_size||"78"} onChange={v=>set("subtitle_font_size",v)} min={20} max={180}/></label><label><span>字体</span><select value={form.subtitle_font||"Microsoft YaHei"} onChange={e=>set("subtitle_font",e.target.value)}>{fontOptions.map(font=><option value={font.value} key={font.value}>{font.label}</option>)}</select></label><label><span>字幕颜色</span><input type="color" value={form.subtitle_color||"#FFFFFF"} onChange={e=>set("subtitle_color",e.target.value)}/></label>
<label><span>每行最多字数</span><NumberControl value={form.subtitle_max_chars_per_line||"14"} onChange={v=>set("subtitle_max_chars_per_line",v)} min={6} max={30}/><small>达到上限后才换行 数值越大第一行越长</small></label>
</div></SettingBlock><SettingBlock title="样式与动效"><div className="modal-grid"><label><span>描边宽度</span><NumberControl value={form.subtitle_outline_width||"1"} onChange={v=>set("subtitle_outline_width",v)} min={0} max={12}/></label><label><span>描边颜色</span><input type="color" value={form.subtitle_outline_color||"#000000"} onChange={e=>set("subtitle_outline_color",e.target.value)}/></label><label><span>下边距</span><NumberControl value={form.subtitle_margin_bottom||"446"} onChange={v=>set("subtitle_margin_bottom",v)} min={0} max={1200}/></label><label><span>字幕动效</span><select value={form.subtitle_effect||"none"} onChange={e=>set("subtitle_effect",e.target.value)}><option value="none">无动效</option><option value="fade">淡入淡出</option><option value="pop">弹跳出现</option><option value="zoom">缩放出现</option><option value="slide_up">向上浮入</option><option value="slide_left">左侧滑入</option></select></label><label><span>动效时长</span><NumberControl value={form.subtitle_effect_duration||"160"} onChange={v=>set("subtitle_effect_duration",v)} min={60} max={500} step={20}/></label></div></SettingBlock></div>}</div><aside className="title-preview"><b>FFmpeg 成片预览</b><div className="title-preview-phone">{tab==="title"?<>{renderedPreview&&<img className="title-rendered-preview" src={renderedPreview}/>}<div className={`preview-title ${renderedPreview?"rendered-drag-layer":""}`} style={titleStyle}><strong style={titleLineStyle(titleMain,"title_main")} onPointerDown={e=>e.currentTarget.setPointerCapture(e.pointerId)} onPointerMove={e=>dragTitle("title_main",e)}>{titleMain}</strong>{titleSub&&<small style={titleLineStyle(titleSub,"title_sub")} onPointerDown={e=>e.currentTarget.setPointerCapture(e.pointerId)} onPointerMove={e=>dragTitle("title_sub",e)}>{titleSub}</small>}</div></>:<div key={`${form.subtitle_effect||"none"}-${form.subtitle_effect_duration||"160"}`} className={`preview-subtitle subtitle-effect-${form.subtitle_effect||"none"}`} style={{...subtitleStyle,"--effect-ms":`${Number(form.subtitle_effect_duration||160)}ms`}}>{subtitlePreviewText}</div>}<span>拖动主标题或副标题可调整位置；字幕保持在下边距内</span></div></aside></div><footer><span>保存后作为全局默认，下次打开自动载入</span><Button quiet onClick={onClose}>取消</Button><Button primary onClick={save}>保存为默认</Button></footer></div></div>}

function Editor({db,refresh,setPage,notify}){const initial=Number(localStorage.getItem("active_template_id"))||db.templates[0]?.id||0;const [tid,setTid]=useState(initial);const[profileId,setProfileId]=useState(db.profiles[0]?.id||0);const[generation,setGeneration]=useState(db.settings);const[showVoice,setShowVoice]=useState(true);const[showSubtitle,setShowSubtitle]=useState(false);const[rewriteBusy,setRewriteBusy]=useState(false);useEffect(()=>setGeneration(db.settings),[db.settings]);useEffect(()=>{if(!db.templates.some(t=>t.id===tid)&&db.templates[0])setTid(db.templates[0].id)},[db.templates]);const template=db.templates.find(t=>t.id===tid);const shots=db.shots.filter(s=>s.template_id===tid);const selected=shots[0];const add=async()=>{if(!tid)return notify("请先创建模板");await request("/api/shots",{method:"POST",body:{template_id:tid,shot_name:`镜头${shots.length+1}`,original_text:"",ai_text:"",material_category_id:db.categories[0]?.id,mute_original_audio:true,enable_subtitle:true,enable_tts:true}});refresh()};const task=async()=>{try{const r=await request("/api/tasks",{method:"POST",body:{template_id:tid,task_name:`${template.name}-${new Date().toLocaleString()}`}});notify(`任务 #${r.id} 已创建，请在任务中心点击开始合成`);await refresh();setPage("任务中心")}catch(e){notify(`创建任务失败：${e.message}`)}};const flag=key=>String(generation[key]||"0")==="1";const persist=async patch=>{setGeneration(v=>({...v,...patch}));await request("/api/settings",{method:"POST",body:patch})};const chooseBgm=async()=>{const picked=await request("/api/select-folder",{method:"POST",body:{}});if(!picked.path)return;const result=await request("/api/bgm/scan",{method:"POST",body:{folder_path:picked.path}});notify(`BGM 扫描完成：${result.total} 首`);refresh()};const createTemplate=async()=>{const name=prompt("请输入新模板名称");if(!name||!name.trim())return;try{const r=await request("/api/templates",{method:"POST",body:{name:name.trim(),description:"用户自定义模板"}});setTid(r.id);localStorage.setItem("active_template_id",r.id);notify("模板已创建，可以开始添加镜头");await refresh()}catch(e){notify("创建模板失败："+e.message)}};const renameTemplate=async t=>{const name=prompt("修改模板名称",t.name||"");if(name===null||!name.trim()||name.trim()===t.name)return;try{await request("/api/templates",{method:"POST",body:{id:t.id,name:name.trim(),description:t.description||""}});setTid(t.id);localStorage.setItem("active_template_id",t.id);notify("模板名称已修改");await refresh()}catch(e){notify("修改失败："+e.message)}};return <div className="simple-editor-page"><div className="simple-guide"><span>左侧选择用户模板，中间编辑真实镜头并生成语音、匹配素材，右侧预览当前素材；完成后点击创建任务。</span></div><div className="simple-editor-grid"><aside className="simple-template-pane"><div className="simple-panel-title simple-template-title"><div><h2>模板选择</h2><p>模板全部由用户创建</p></div><button type="button" className="simple-new-template" onClick={createTemplate}><Icon name="plus" size={14}/>新增模板</button></div><div className="simple-list-head"><b>我的自定义模板</b><span>共 {db.templates.length} 个</span></div><div className="simple-template-list">{db.templates.map(t=><div key={t.id} className={`simple-template-item ${tid===t.id?"active":""}`}><button className="simple-template-select" onClick={()=>{setTid(t.id);localStorage.setItem("active_template_id",t.id)}}><div><b>{t.name}</b><span>自定义</span></div><small>{t.shot_count} 个镜头</small></button><button type="button" className="simple-template-rename" title="修改模板名称" onClick={()=>renameTemplate(t)}>改名</button></div>)}</div></aside><main className="simple-creation-pane"><div className="simple-creation-head"><div><h2>模板创作区</h2><p>{template?.name||"请创建模板"}</p></div></div><div className="simple-edit-tab"><span>逐句编辑</span></div><div className="simple-toolbar"><label>账号档案<select value={profileId} onChange={e=>setProfileId(Number(e.target.value))}>{db.profiles.map(p=><option value={p.id} key={p.id}>{p.company_name}</option>)}</select></label><Button quiet disabled={rewriteBusy} onClick={async()=>{if(!tid||rewriteBusy)return;try{setRewriteBusy(true);const started=performance.now();await request(`/api/templates/${tid}/rewrite-all`,{method:"POST",body:{profile_id:profileId}});notify(`全部镜头改写完成，用时 ${((performance.now()-started)/1000).toFixed(1)} 秒`);await refresh()}catch(e){notify("批量改写失败："+e.message)}finally{setRewriteBusy(false)}}}>{rewriteBusy?"正在批量改写…":"AI 改写全部"}</Button><Button quiet onClick={refresh}>保存模板</Button></div><div className="simple-divider"/><div className="simple-shot-list">{shots.map(s=><ShotCard key={s.id} shot={s} categories={db.categories} voices={db.tts_voices} profileId={profileId} refresh={refresh} notify={notify}/>)}<button className="simple-add-shot" onClick={add}><Icon name="plus"/>添加镜头</button><section className="simple-generation-settings generation-card"><div className="simple-setting-row bgm-row"><b>背景音乐</b><button type="button" aria-label="切换背景音乐" aria-pressed={flag("bgm_enabled")} onClick={()=>persist({bgm_enabled:flag("bgm_enabled")?"0":"1"})} className={`switch ${flag("bgm_enabled")?"on":""}`}><i/></button><p>开启后使用下方文件夹中的音频，可选择固定曲目或随机一条</p><div className="simple-setting-control"><input readOnly value={generation.bgm_dir||"尚未选择 BGM 目录"}/><div><Button quiet onClick={chooseBgm}>选择本地文件夹</Button><span>曲目</span></div><select value={generation.default_bgm_id||""} onChange={e=>persist({default_bgm_id:e.target.value})}><option value="">随机</option>{db.bgms.map(b=><option value={b.id} key={b.id}>{b.name}</option>)}</select></div></div><div className="simple-setting-row voice-setting-row"><b>智能配音</b><button type="button" aria-label="切换智能配音" aria-pressed={flag("tts_enabled")} onClick={()=>persist({tts_enabled:flag("tts_enabled")?"0":"1"})} className={`switch ${flag("tts_enabled")?"on":""}`}><i/></button><p>自定义模板可关闭配音</p><span className="setting-side-label">音色</span><select value={generation.default_tts_voice_id||""} onChange={e=>persist({default_tts_voice_id:e.target.value})}><option value="">默认音色</option>{db.tts_voices.map(v=><option value={v.id} key={v.id}>{v.name}</option>)}</select></div><div className="simple-setting-row sound-config-row"><b>声音配置</b><Button quiet onClick={()=>setShowVoice(v=>!v)}>{showVoice?"收起声音配置":"展开声音配置"}</Button></div>{showVoice&&<div className="generation-sliders"><label><b>语速</b><input type="range" min="0.5" max="2" step="0.1" value={generation.tts_speed||1} onChange={e=>persist({tts_speed:e.target.value})}/><span>{Number(generation.tts_speed||1).toFixed(1)}</span></label><label><b>人声音量</b><input type="range" min="0" max="3" step="0.1" value={generation.voice_volume||1} onChange={e=>persist({voice_volume:e.target.value})}/><span>{Number(generation.voice_volume||1).toFixed(1)}</span></label><label><b>背景音乐音量</b><input type="range" min="0" max="1" step="0.05" value={generation.bgm_volume||0.15} onChange={e=>persist({bgm_volume:e.target.value})}/><span>{Number(generation.bgm_volume||0.15).toFixed(2)}</span></label><label title="文案空格分段之间的停顿时间"><b>分段停顿</b><input type="range" min="0" max="300" step="10" value={generation.tts_segment_gap_ms||60} onChange={e=>persist({tts_segment_gap_ms:e.target.value})}/><span>{Number(generation.tts_segment_gap_ms||60).toFixed(0)}ms</span></label></div>}<div className="simple-setting-row subtitle-config-row"><b>标题/字幕</b><Button quiet onClick={()=>setShowSubtitle(true)}>顶部标题及字幕设置</Button></div><Button primary className="create-task-button" onClick={task}>创建任务</Button></section>{showSubtitle&&<TitleSubtitleModal settings={generation} onClose={()=>setShowSubtitle(false)} onSaved={setGeneration} notify={notify}/>}</div></main><aside className="simple-preview-pane"><div className="simple-panel-title"><h2>成片预览</h2><p>{selected?.matched_file_name||"当前镜头尚未匹配素材"}</p></div><div className="simple-phone">{selected?.matched_file_path?<video className="simple-phone-screen" src={`/media?path=${encodeURIComponent(selected.matched_file_path)}`} controls muted/>:<div className="simple-phone-screen"><button><Icon name="play" size={25}/></button></div>}</div><div className="simple-preview-note"><b>说明：</b><span>这里显示数据库中当前镜头实际匹配的视频文件。</span></div></aside></div></div>}

function BatchPage({db,refresh,setPage,notify}){
  const firstTemplate=db.templates[0]?.id||0;
  const[templateId,setTemplateId]=useState(firstTemplate);
  const[name,setName]=useState("");
  const[count,setCount]=useState(3);
  const[strategy,setStrategy]=useState("prefer_unused");
  const[categories,setCategories]=useState([]);
  const[busy,setBusy]=useState(false);
  const template=db.templates.find(t=>t.id===Number(templateId));
  const required=[...new Set(db.shots.filter(s=>s.template_id===Number(templateId)&&s.material_category_id).map(s=>s.material_category_id))];
  useEffect(()=>{setCategories(required)},[templateId,db.shots.length]);
  const toggle=id=>setCategories(v=>v.includes(id)?v.filter(x=>x!==id):[...v,id]);
  const poolCount=db.materials.filter(m=>categories.includes(m.category_id)).length;
  const start=async()=>{if(!templateId)return notify("请先选择模板");setBusy(true);try{await request("/api/batches",{method:"POST",body:{name:name.trim(),template_id:Number(templateId),total_count:Number(count),material_strategy:strategy,category_ids:categories}});notify("批量任务已创建，正在串行生成");await refresh(false);setPage("任务中心")}finally{setBusy(false)}};
  const strategies=[["random","随机组合","每条视频独立随机选择素材，适合快速出片。"],["prefer_unused","优先未使用素材","优先使用本批次尚未出现的素材，不足时自动复用。"],["avoid_repeat","避免重复","本批次不允许复用素材，素材不足时停止对应任务。"]];
  return <div className="batch-page">
    <div className="page-title-row"><div><p className="eyebrow">BATCH PRODUCTION</p><h1>批量生成</h1><p>每条任务先生成不同文案，再依次完成配音、字幕、素材匹配和成片。</p></div><Button quiet onClick={refresh}>刷新</Button></div>
    <div className="batch-layout"><section className="batch-form-card">
      <div className="batch-section"><b>01 选择模板</b><select value={templateId} onChange={e=>setTemplateId(Number(e.target.value))}><option value="">请选择模板</option>{db.templates.map(t=><option key={t.id} value={t.id}>{t.name} · {t.shot_count||0} 镜头</option>)}</select>{template&&<small>将按“{template.name}”创建独立生成任务。</small>}</div>
      <div className="batch-section"><b>02 选择素材池</b><div className="batch-category-grid">{db.categories.map(c=>{const active=categories.includes(c.id);const n=db.materials.filter(m=>m.category_id===c.id).length;return <button key={c.id} className={active?"active":""} onClick={()=>toggle(c.id)}><span>{c.name}</span><small>{n} 个素材{required.includes(c.id)?" · 模板需要":""}</small></button>})}</div><small>当前素材池共 {poolCount} 个视频。模板所需分类必须全部选中。</small></div>
      <div className="batch-section"><b>03 生成设置</b><div className="batch-field-row"><label>批次名称<input value={name} onChange={e=>setName(e.target.value)} placeholder={template?`${template.name} 批量生成`:"输入批次名称"}/></label><label>生成数量<input type="number" min="1" max="100" value={count} onChange={e=>setCount(Math.max(1,Math.min(100,Number(e.target.value)||1)))}/></label></div></div>
      <div className="batch-section"><b>04 素材策略</b><div className="batch-strategies">{strategies.map(([id,title,desc])=><button key={id} className={strategy===id?"active":""} onClick={()=>setStrategy(id)}><i>{strategy===id?"✓":""}</i><span><strong>{title}</strong><small>{desc}</small></span></button>)}</div></div>
      <div className="batch-submit"><div><strong>预计创建 {count} 个任务和 {count} 套独立文案</strong><small>串行执行：独立改写 → 配音 → 字幕 → 素材匹配 → 成片。</small></div><Button primary disabled={busy||!templateId||!categories.length} onClick={start}>{busy?"正在创建…":"开始批量生成"}</Button></div>
    </section><aside className="batch-side-card"><h2>最近批次</h2>{db.batch_tasks.length?db.batch_tasks.slice(0,6).map(b=><div className="batch-mini" key={b.id}><div><b>{b.name}</b><small>{b.completed_count}/{b.total_count} 完成 · {b.failed_count} 失败</small></div><span>{b.progress||0}%</span><i><em style={{width:`${b.progress||0}%`}}/></i></div>):<div className="batch-empty">还没有批量任务</div>}</aside></div>
  </div>
}

function TasksPage({db,refresh,notify}){const[storage,setStorage]=useState(db.settings);const[selectedId,setSelectedId]=useState(db.tasks[0]?.id||0);useEffect(()=>setStorage(db.settings),[db.settings]);useEffect(()=>{if(!db.tasks.some(t=>t.id===selectedId))setSelectedId(db.tasks[0]?.id||0)},[db.tasks,selectedId]);const selected=db.tasks.find(t=>t.id===selectedId)||db.tasks[0];const statusText={pending:"等待合成",running:"生成中",processing_shot:"处理分镜",merging:"合并中",completed:"已完成",failed:"失败"};const persist=async patch=>{setStorage(v=>({...v,...patch}));await request("/api/settings",{method:"POST",body:patch});refresh(false)};const choose=async key=>{const r=await request("/api/select-folder",{method:"POST",body:{}});if(r.path)await persist({[key]:r.path})};const generate=async id=>{await request(`/api/tasks/${id}/generate`,{method:"POST",body:{}});notify("任务已开始合成");refresh()};const remove=async id=>{await request(`/api/tasks/${id}`,{method:"DELETE"});notify("任务已删除");refresh()};const clearCompleted=async()=>{const r=await request("/api/tasks/clear-completed",{method:"POST",body:{}});notify(`已清除 ${r.deleted} 个已完成任务`);refresh()};return <div className="task-replica-page"><div className="task-page-heading"><h1>任务中心</h1><Button quiet onClick={refresh}>刷新状态</Button></div><section className="task-replica-board"><div className="task-guide">以下为当前混剪任务列表，与镜头剪辑页创建的真实任务数据共用。</div>
{db.batch_tasks.length>0&&<section className="task-batch-overview"><div className="task-batch-title"><div><h2>批量任务</h2><p>串行队列会逐条调用现有视频生成流程。</p></div><span>{db.batch_tasks.filter(b=>["pending","running"].includes(b.status)).length} 个进行中</span></div><div className="task-batch-list">{db.batch_tasks.slice(0,3).map(b=><article key={b.id} className="task-batch-card"><div className="task-batch-card-head"><div><b>{b.name}</b><small>{b.template_name} · {b.total_count} 条</small></div><i className={`batch-status ${b.status}`}>{({pending:"等待中",running:"生成中",completed:"已完成",completed_with_errors:"部分失败",failed:"失败"})[b.status]||b.status}</i></div><div className="task-batch-numbers"><span><strong>{b.completed_count}</strong>完成</span><span><strong>{b.failed_count}</strong>失败</span><span><strong>{Math.max(0,b.total_count-b.completed_count-b.failed_count)}</strong>剩余</span><em>{b.progress||0}%</em></div><div className="task-batch-progress"><i style={{width:`${b.progress||0}%`}}/></div>{db.batch_items.find(i=>i.batch_id===b.id&&i.status==="running")&&<p>当前：{db.batch_items.find(i=>i.batch_id===b.id&&i.status==="running")?.current_shot||"正在准备"}</p>}</article>)}</div></section>}
<section className="task-storage-card"><h2>存储设置</h2><div className="task-storage-body"><label><span>工作缓存目录</span><input value={storage.work_dir||""} onChange={e=>setStorage({...storage,work_dir:e.target.value})} onBlur={()=>persist({work_dir:storage.work_dir||""})}/><Button quiet onClick={()=>choose("work_dir")}>选择目录</Button><Button className="task-clear-path" onClick={()=>persist({work_dir:""})}>清空</Button><small>配音、字幕和分镜渲染中间文件写入该目录。</small></label><label><span>成片目录</span><input value={storage.output_dir||""} onChange={e=>setStorage({...storage,output_dir:e.target.value})} onBlur={()=>persist({output_dir:storage.output_dir||""})}/><Button quiet onClick={()=>choose("output_dir")}>选择目录</Button><Button className="task-clear-path" onClick={()=>persist({output_dir:""})}>清空</Button><small>成片目录用于保存最终导出的 MP4 文件。</small></label></div></section><div className="task-list-toolbar"><Button quiet onClick={clearCompleted}>清除已完成</Button><span>共 {db.tasks.length} 个任务</span></div><div className="task-list-preview-grid"><section className="task-table-card"><div className="task-table-head"><span>模板类型</span><span>镜头数</span><span>创建时间</span><span>状态</span><span>操作</span></div><div className="task-table-body">{db.tasks.length?db.tasks.map(t=><div key={t.id} className={`task-table-row ${selected?.id===t.id?"selected":""}`} onClick={()=>setSelectedId(t.id)}><span><b>{t.template_name||t.task_name}</b><small>{t.task_name}</small></span><span>{t.total_shots||0}</span><span>{t.created_at}</span><span><i className={`task-status ${t.status}`}>{t.batch_id&&t.status==="pending"?"排队中":statusText[t.status]||t.status}</i>{!["completed","failed","pending"].includes(t.status)&&<small>{t.progress||0}%</small>}</span><span className="task-row-actions">{!t.batch_id&&t.status!=="completed"&&t.status!=="running"&&t.status!=="processing_shot"&&t.status!=="merging"&&<button onClick={e=>{e.stopPropagation();generate(t.id)}}>{t.status==="failed"?"重新合成":"开始合成"}</button>}<button className="delete" onClick={e=>{e.stopPropagation();remove(t.id)}}>删除</button></span></div>):<div className="task-table-empty">暂无生成任务</div>}</div></section><aside className="task-preview-card"><h2><Icon name="play" size={15}/>成片预览</h2><div className="task-preview-phone">{selected?.output_url?<video src={selected.output_url} controls/>:<div><span><Icon name="film" size={28}/></span><b>{selected?statusText[selected.status]||selected.status:"暂无成片"}</b><small>{selected?.progress||0}%</small></div>}</div>{selected&&<p>{selected.output_path||selected.error_message||"生成完成后可在此预览"}</p>}</aside></div></section></div>}

function AiServicesPanel({db,refresh,notify}){
 const emptyForm={name:"",provider:"openai_compatible",base_url:"",api_key:"",model:"",timeout_seconds:60,is_enabled:true,is_default:false,system_prompt:""};
 const[id,setId]=useState(db.ai_services[0]?.id||0);
 const[form,setForm]=useState(db.ai_services[0]||emptyForm);
 const[open,setOpen]=useState(false);
 useEffect(()=>{const value=db.ai_services.find(x=>x.id===id);if(value)setForm(value)},[id,db.ai_services]);
 const edit=value=>{setId(value.id);setForm({...value});setOpen(true)};
 const create=()=>{setId(0);setForm({...emptyForm});setOpen(true)};
 const save=async()=>{try{const r=await request("/api/ai-services",{method:"POST",body:form});setId(r.id);setForm(v=>({...v,id:r.id}));notify("AI 服务已保存");await refresh();setOpen(false)}catch(e){notify("保存失败："+e.message)}};
 const test=async()=>{try{if(!form.id)return notify("请先保存服务");const r=await request("/api/ai-services/"+form.id+"/test",{method:"POST",body:{}});notify("连接成功："+r.message)}catch(e){notify(String(e.message||"").startsWith("连接失败")?e.message:"连接失败："+e.message)}};
 const remove=async()=>{if(!form.id||!confirm("确定删除该AI服务？"))return;await request("/api/ai-services/"+form.id,{method:"DELETE"});setId(0);setForm({...emptyForm});setOpen(false);notify("AI 服务已删除");refresh()};
 return <section className="service-center ai-service-center"><div className="service-center-head"><div><span>AI SERVICE CENTER</span><h2>AI 服务配置中心</h2><p>使用 OpenAI-compatible Chat Completions 接口，配置保存在本地 SQLite。</p></div><div className="service-head-actions">{db.ai_services.length>0&&<Button quiet onClick={()=>edit(db.ai_services.find(x=>x.id===id)||db.ai_services[0])}>配置当前服务</Button>}<Button primary onClick={create}>新建服务</Button></div></div><div className="ai-service-cards">{db.ai_services.map(x=><article className={id===x.id?"active":""} key={x.id}><div><b>{x.name}</b><small>{x.model||"未填写模型"}</small></div><span className={x.is_enabled?"enabled":"disabled"}>{x.is_enabled?"已启用":"已停用"}</span><Button quiet onClick={()=>edit(x)}>配置</Button></article>)}{db.ai_services.length===0&&<button className="empty-service-card" onClick={create}>尚未配置 AI 服务，点击新建</button>}</div>{open&&<div className="service-modal-mask" onMouseDown={e=>e.target===e.currentTarget&&setOpen(false)}><div className="service-modal"><header><div><span>AI SERVICE CONFIG</span><h2>{form.id?"配置 AI 服务":"新建 AI 服务"}</h2></div><button type="button" onClick={()=>setOpen(false)}>×</button></header><div className="service-form"><label>服务名称<input autoFocus value={form.name||""} onChange={e=>setForm({...form,name:e.target.value})}/></label><label>服务类型<select value={form.provider||"openai_compatible"} onChange={e=>{const provider=e.target.value;setForm({...form,provider,...(provider==="minimax"?{base_url:"https://api.minimaxi.com",model:"speech-2.8-hd",response_format:"mp3"}:{})})}}><option value="openai_compatible">OpenAI Compatible</option></select></label><label className="wide">Base URL<input placeholder="https://example.com/v1" value={form.base_url||""} onChange={e=>setForm({...form,base_url:e.target.value})}/></label><label>API Key<input type="password" value={form.api_key||""} onChange={e=>setForm({...form,api_key:e.target.value})}/></label><label>模型<input value={form.model||""} onChange={e=>setForm({...form,model:e.target.value})}/></label><label>超时（秒）<input type="number" value={form.timeout_seconds||60} onChange={e=>setForm({...form,timeout_seconds:Number(e.target.value)})}/></label><label className="check-label"><input type="checkbox" checked={!!form.is_enabled} onChange={e=>setForm({...form,is_enabled:e.target.checked})}/>启用</label><label className="check-label"><input type="checkbox" checked={!!form.is_default} onChange={e=>setForm({...form,is_default:e.target.checked})}/>设为默认</label><label className="wide">系统提示词<textarea value={form.system_prompt||""} onChange={e=>setForm({...form,system_prompt:e.target.value})}/></label></div><footer>{form.id&&<Button quiet onClick={remove}>删除服务</Button>}<span/><Button quiet onClick={()=>setOpen(false)}>取消</Button><Button quiet onClick={test}>测试连接</Button><Button primary onClick={save}>保存服务</Button></footer></div></div>}</section>
}

function SettingsPage({db,refresh,notify}){const [form,setForm]=useState(db.settings);useEffect(()=>setForm(db.settings),[db.settings]);const choose=async key=>{const r=await request("/api/select-folder",{method:"POST",body:{}});if(r.path)setForm({...form,[key]:r.path});return r.path};const save=async()=>{await request("/api/settings",{method:"POST",body:form});notify("设置已保存");refresh()};const scanBgm=async()=>{const folder=await choose("bgm_dir");if(!folder)return;const r=await request("/api/bgm/scan",{method:"POST",body:{folder_path:folder}});notify("BGM 扫描完成："+r.total+" 首");refresh()};const toggleSfx=async()=>{const enabled=String(form.sfx_enabled||"1")==="1"?"0":"1";setForm({...form,sfx_enabled:enabled});await request("/api/settings",{method:"POST",body:{sfx_enabled:enabled}});notify(enabled==="1"?"\u97f3\u6548\u5df2\u5f00\u542f":"\u97f3\u6548\u5df2\u5173\u95ed");refresh(false)};return <div className="page"><PageHeader kicker="SYSTEM" title="系统设置" desc="配置本地引擎、AI 服务和外部 TTS。"><Button primary onClick={save}>保存基础设置</Button></PageHeader><div className="settings-card"><label>FFmpeg 路径<input value={form.ffmpeg_path||""} onChange={e=>setForm({...form,ffmpeg_path:e.target.value})}/></label><label>FFprobe 路径<input value={form.ffprobe_path||""} onChange={e=>setForm({...form,ffprobe_path:e.target.value})}/></label><label>成片输出目录<div><input value={form.output_dir||""} onChange={e=>setForm({...form,output_dir:e.target.value})}/><Button quiet onClick={()=>choose("output_dir")}>选择目录</Button></div></label><label>BGM 目录<div><input value={form.bgm_dir||""} onChange={e=>setForm({...form,bgm_dir:e.target.value})}/><Button quiet onClick={scanBgm}>选择并扫描</Button></div></label><p>已收录 {db.bgms.length} 首背景音乐，默认混音音量 15%。</p><p className="settings-sfx-toggle"><span>{"\u81ea\u52a8\u97f3\u6548"}</span><button type="button" className={`switch ${String(form.sfx_enabled||"1")==="1"?"on":""}`} onClick={toggleSfx}><i/></button><small>{String(form.sfx_enabled||"1")==="1"?"\u5df2\u5f00\u542f \u4e0d\u4f1a\u538b\u4f4e\u914d\u97f3":"\u5df2\u5173\u95ed"}</small></p><div className="natural-color-setting"><div><b>{"\u81ea\u7136\u589e\u8272\u6ee4\u955c"}</b><small>{"\u8ba9\u6210\u7247\u989c\u8272\u66f4\u901a\u900f\u66f4\u6709\u8d28\u611f\u9002\u5408\u5927\u591a\u6570\u4ea7\u54c1\u5c55\u793a\u548c\u5de5\u5382\u73af\u5883\u89c6\u9891"}</small></div><button type="button" aria-label="natural-color-filter" className={`switch ${String(form.natural_color_filter_enabled??"1")==="1"?"on":""}`} onClick={()=>setForm({...form,natural_color_filter_enabled:String(form.natural_color_filter_enabled??"1")==="1"?"0":"1"})}><i/></button><label>{"\u6ee4\u955c\u5f3a\u5ea6"}<select disabled={String(form.natural_color_filter_enabled??"1")!=="1"} value={form.natural_color_filter_strength||"standard"} onChange={e=>setForm({...form,natural_color_filter_strength:e.target.value})}><option value="weak">{"\u5f31"}</option><option value="standard">{"\u6807\u51c6"}</option><option value="strong">{"\u7a0d\u5f3a"}</option></select></label></div><div className="end-hold-setting"><div><b>{"\u7ed3\u5c3e\u505c\u7559\u65f6\u95f4"}</b><small>{"\u6700\u540e\u4e00\u53e5\u8bed\u97f3\u64ad\u653e\u5b8c\u540e\u4fdd\u7559\u753b\u9762\u907f\u514d\u5c3e\u97f3\u88ab\u622a\u65ad"}</small></div><label>{"\u505c\u7559\u65f6\u957f"}<select value={String(form.end_hold_duration||"0.8")} onChange={e=>setForm({...form,end_hold_duration:e.target.value})}><option value="0.3">0.3 {"\u79d2"}</option><option value="0.5">0.5 {"\u79d2"}</option><option value="0.8">0.8 {"\u79d2"}</option><option value="1.0">1.0 {"\u79d2"}</option><option value="1.5">1.5 {"\u79d2"}</option></select></label></div></div><UpdateSettings db={db} refresh={refresh} notify={notify} Button={Button} Icon={Icon}/><AiServicesPanelV2 db={db} refresh={refresh} notify={notify} request={request} Button={Button}/><TtsServicesPanel db={db} refresh={refresh} notify={notify}/></div>}
function PublishDraftCard({video,accounts,profiles,autoMode,refresh,notify,onPreview}){const[form,setForm]=useState({generation_task_id:video.id,title:video.task_name||"",description:"",tags:"",cover_path:"",cover_text:"",scheduled_at:"",delete_after_publish:false,account_ids:[],ai_title:"",ai_description:"",ai_hashtags:[],ai_generated_time:""});const[showAccounts,setShowAccounts]=useState(false);const[scheduleMode,setScheduleMode]=useState("now");const[aiBusy,setAiBusy]=useState("");const[busy,setBusy]=useState(false);const[titleOptions,setTitleOptions]=useState([]);const toggle=id=>setForm(value=>({...value,account_ids:value.account_ids.includes(id)?value.account_ids.filter(item=>item!==id):[...value.account_ids,id]}));const platform=accounts.find(item=>form.account_ids.includes(item.id))?.platform_code||"douyin";const ai=async mode=>{try{setAiBusy(mode);const result=await request("/api/publish/ai-content",{method:"POST",body:{video_id:video.id,platform,profile_id:profiles[0]?.id||0,current_title:form.title}});if(mode==="title"){setTitleOptions(result.titles||[]);setForm(value=>({...value,title:result.title,ai_title:result.title,ai_generated_time:result.ai_generated_time}))}else if(mode==="tags"){setForm(value=>({...value,tags:(result.hashtags||[]).map(item=>"#"+item).join(" "),ai_hashtags:result.hashtags||[],ai_generated_time:result.ai_generated_time}))}else{setTitleOptions(result.titles||[]);setForm(value=>({...value,title:result.title,description:result.description,tags:(result.hashtags||[]).map(item=>"#"+item).join(" "),cover_text:result.cover_text,ai_title:result.title,ai_description:result.description,ai_hashtags:result.hashtags||[],ai_generated_time:result.ai_generated_time}))}notify("AI内容已生成，可继续修改")}catch(error){notify(error.message)}finally{setAiBusy("")}};const cover=async()=>{const result=await request("/api/select-cover",{method:"POST",body:{}});if(result.path)setForm(value=>({...value,cover_path:result.path}))};const remove=async()=>{if(!confirm(video.output_exists?"\u786e\u5b9a\u5220\u9664\u8fd9\u6761\u6210\u7247\u8bb0\u5f55\uff1f\u539f\u89c6\u9891\u6587\u4ef6\u4e0d\u4f1a\u5220\u9664\u3002":"\u6210\u7247\u6587\u4ef6\u5df2\u4e0d\u5b58\u5728\uff0c\u786e\u5b9a\u6e05\u7406\u8fd9\u6761\u65e0\u6548\u8bb0\u5f55\uff1f"))return;await request(`/api/tasks/${video.id}`,{method:"DELETE"});notify("\u6210\u7247\u8bb0\u5f55\u5df2\u5220\u9664");refresh(false)};const submit=async()=>{if(!video.output_exists)return notify("\u6210\u7247\u6587\u4ef6\u4e0d\u5b58\u5728\uff0c\u8bf7\u5220\u9664\u8bb0\u5f55\u540e\u91cd\u65b0\u751f\u6210");if(scheduleMode==="timed"&&!form.scheduled_at)return notify("\u8bf7\u9009\u62e9\u5b9a\u65f6\u53d1\u5e03\u65f6\u95f4");try{setBusy(true);const result=await request("/api/publish/tasks",{method:"POST",body:form});if(autoMode)await request(`/api/publish/tasks/${result.id}/enqueue`,{method:"POST",body:{}});notify(autoMode?"已创建并加入排队":"已创建，等待手动确认");await refresh(false)}catch(error){notify(error.message)}finally{setBusy(false)}};return <article className={`schedule-card ${!video.output_exists?"missing-output":""}`}><div className="schedule-line"><i/><span>待排期</span><b>{video.created_at?.slice(5,16)} · {video.task_name}</b><em>{form.title&&form.tags?"标题 / 话题已填":"待补标题 / 话题"}</em></div><div className="schedule-editor"><label>发布标题<textarea value={form.title} onChange={e=>setForm({...form,title:e.target.value})}/>{titleOptions.length>0&&<div className="schedule-title-options">{titleOptions.map(title=><button key={title} onClick={()=>setForm({...form,title,ai_title:title})}>{title}</button>)}</div>}</label><label>发布话题<input value={form.tags} onChange={e=>setForm({...form,tags:e.target.value})} placeholder="#行业 #产品 #工厂"/></label><label>发布时间<div className="schedule-time-mode"><button type="button" className={scheduleMode==="now"?"active":""} onClick={()=>{setScheduleMode("now");setForm({...form,scheduled_at:""})}}>立即发布</button><button type="button" className={scheduleMode==="timed"?"active":""} onClick={()=>setScheduleMode("timed")}>定时发布</button></div>{scheduleMode==="timed"&&<input type="datetime-local" value={form.scheduled_at} onChange={e=>setForm({...form,scheduled_at:e.target.value})}/>}</label><label>封面文字<input value={form.cover_text} onChange={e=>setForm({...form,cover_text:e.target.value})} placeholder="3-5字"/></label><button className="schedule-cover" onClick={cover}>{form.cover_path?<><b>已选择封面</b><small>{form.cover_path.split(/[\\/]/).pop()}</small></>:<><Icon name="plus" size={18}/><span>点击选择本地封面</span></>}</button><div className="schedule-actions"><div><Button quiet disabled={!!aiBusy} onClick={()=>ai("title")}>AI标题</Button><Button quiet disabled={!!aiBusy} onClick={()=>ai("tags")}>AI话题</Button><Button quiet disabled={!!aiBusy} onClick={()=>ai("all")}>{aiBusy?"生成中":"AI优化全部"}</Button></div><div><Button quiet onClick={()=>setShowAccounts(value=>!value)}>{form.account_ids.length?`已选 ${form.account_ids.length} 个账号`:"选择发布账号"}</Button><Button quiet onClick={()=>onPreview({url:video.output_url,title:form.title,path:video.output_path})}>预览视频</Button><Button quiet className="draft-delete" onClick={remove}>{video.output_exists?"\u5220\u9664\u8bb0\u5f55":"\u5220\u9664\u65e0\u6548\u8bb0\u5f55"}</Button><Button primary disabled={busy} onClick={submit}>{busy?"处理中":autoMode?"选择账号后排期":"创建待确认任务"}</Button></div><label className="schedule-delete"><input type="checkbox" checked={form.delete_after_publish} onChange={e=>setForm({...form,delete_after_publish:e.target.checked})}/>全部成功后删除本地视频</label></div>{showAccounts&&<div className="schedule-accounts">{accounts.map(account=><button className={form.account_ids.includes(account.id)?"selected":""} key={account.id} onClick={()=>toggle(account.id)}><i>{form.account_ids.includes(account.id)?"✓":account.platform_name.slice(0,1)}</i><span>{account.account_name}<small>{account.platform_name}</small></span></button>)}{accounts.length===0&&<p>暂无账号，请先进入账号管理。</p>}</div>}</div></article>}

function PublishTasksPage({db,refresh,notify,onAccounts,onTests}){const supported=new Set(["douyin","tiktok","youtube","instagram","facebook","xiaohongshu","kuaishou","wechat_channels","bilibili"]);const accounts=db.publish_accounts.filter(account=>supported.has(account.platform_code)&&account.capability_status==="passed");const scheduledIds=new Set(db.publish_tasks.map(task=>task.generation_task_id));const drafts=db.tasks.filter(task=>task.status==="completed"&&task.output_path&&task.output_exists&&!scheduledIds.has(task.id));const[filter,setFilter]=useState("draft");const[autoMode,setAutoMode]=useState(true);const[preview,setPreview]=useState(null);const[syncing,setSyncing]=useState(false);const statusText={pending:"待发布",draft:"草稿",prechecking:"预检中",ready:"准备发布",queued:"排队中",uploading:"上传中",submitting:"提交中",processing:"平台处理中",waiting_confirmation:"待确认",publishing:"发布中",succeeded:"发布成功",success:"成功",needs_login:"需要重新登录",needs_manual_action:"需要人工处理",cancelled:"已取消",failed:"失败"};const queueStatuses=["pending","ready","prechecking","queued","uploading","submitting","processing","waiting_confirmation","publishing","failed","needs_login","needs_manual_action"];const visible=filter==="queue"?db.publish_tasks.filter(task=>queueStatuses.includes(task.status)):db.publish_tasks.filter(task=>["success","succeeded"].includes(task.status));const enqueue=async id=>{try{await request(`/api/publish/tasks/${id}/enqueue`,{method:"POST",body:{}});notify("任务已加入队列");refresh(false)}catch(error){notify(error.message)}};const remove=async id=>{if(!confirm("确定删除该发布任务？"))return;await request(`/api/publish/tasks/${id}`,{method:"DELETE"});refresh(false)};const syncOutput=async()=>{try{setSyncing(true);const result=await request("/api/publish/sync-output",{method:"POST",body:{}});await refresh(false);const skipped=result.skipped_publishing_tasks?` 另有 ${result.skipped_publishing_tasks} 个发布中任务未处理`:"";notify(`\u5df2\u626b\u63cf\u8f93\u51fa\u76ee\u5f55 ${result.scanned_outputs} \u4e2a\u89c6\u9891 \u6e05\u7406 ${result.removed_publish_tasks} \u4e2a\u53d1\u5e03\u4e2d\u5fc3\u8bb0\u5f55${skipped}`)}catch(error){notify(error.message)}finally{setSyncing(false)}};return <div className="page schedule-page"><PageHeader kicker="PUBLISH SCHEDULE" title="发布排期" desc="批量生成成功的成片会自动进入待排期列表。"><Button quiet icon="folder" disabled={syncing} onClick={syncOutput}>{syncing?"正在扫描":"同步输出目录"}</Button><Button quiet onClick={onAccounts}>账号管理</Button>{db.admin_mode&&<Button quiet onClick={onTests}>平台发布测试</Button>}</PageHeader><div className="schedule-shell"><main><div className="schedule-guide">批量生成成功的成片会自动出现在本页。为视频补充标题、话题和账号后即可加入排期。</div><section className="schedule-stats"><article><strong>{drafts.length}</strong><span>待排期视频</span></article><article><strong>{db.publish_tasks.filter(task=>["prechecking","queued","uploading","submitting","processing","waiting_confirmation","publishing"].includes(task.status)).length}</strong><span>排期中</span></article><article><strong>{drafts.length}</strong><span>待补标题 / 话题</span></article><article><strong>{db.publish_tasks.filter(task=>["success","succeeded"].includes(task.status)).length}</strong><span>已有发布结果</span></article></section><div className="schedule-toolbar"><nav><button className={filter==="draft"?"active":""} onClick={()=>setFilter("draft")}>未排期</button><button className={filter==="queue"?"active":""} onClick={()=>setFilter("queue")}>排期中</button><button className={filter==="result"?"active":""} onClick={()=>setFilter("result")}>已有结果</button></nav><div><b>发布方式</b><button className={autoMode?"active":""} onClick={()=>setAutoMode(true)}>自动发布</button><button className={!autoMode?"active":""} onClick={()=>setAutoMode(false)}>手动确认</button></div></div><h2 className="schedule-list-title">排期列表</h2><section className="schedule-list">{filter==="draft"?drafts.map(video=><PublishDraftCard key={video.id} video={video} accounts={accounts} profiles={db.profiles} autoMode={autoMode} refresh={refresh} notify={notify} onPreview={setPreview}/>):visible.map(task=><article className="scheduled-card" key={task.id} onClick={()=>setPreview({url:task.video_url,title:task.title,path:task.video_path})}><span className={`publish-task-status ${task.status}`}>{statusText[task.status]}</span><div><b>{task.title}</b><small>{task.video_path.split(/[\\/]/).pop()} · {task.channels.map(item=>item.platform_name).join(" / ")}</small></div><em>{task.scheduled_at||"立即发布"}</em><div>{["pending","failed"].includes(task.status)&&<Button quiet onClick={event=>{event.stopPropagation();enqueue(task.id)}}>加入队列</Button>}<button onClick={event=>{event.stopPropagation();remove(task.id)}}>删除</button></div></article>)}{(filter==="draft"?drafts:visible).length===0&&<div className="schedule-empty">当前没有对应视频</div>}</section></main><aside className="schedule-preview"><h3>通用预览</h3><div>{preview?.url?<video src={preview.url} controls preload="metadata"/>:<span>点击卡片上的“预览视频”<br/>在此处播放成片</span>}</div><b>{preview?.title||"尚未选择视频"}</b></aside></div></div>}

function PublishCenter({db,refresh,notify}){const[view,setView]=useState("tasks");return view==="tests"?<PlatformTestPage db={db} refresh={refresh} notify={notify} request={request} Button={Button} onBack={()=>setView("tasks")}/>:view==="accounts"?<PublishPage db={db} refresh={refresh} notify={notify} onTasks={()=>setView("tasks")} onTests={()=>setView("tests")}/>:<PublishTasksPage db={db} refresh={refresh} notify={notify} onAccounts={()=>setView("accounts")} onTests={()=>setView("tests")}/>}

function PublishPage({db,refresh,notify,onTasks,onTests}){
 const platforms=db.platforms.filter(p=>p.enabled);
 const[platformId,setPlatformId]=useState(platforms[0]?.id||0);
 const[accountName,setAccountName]=useState("");
 const[clientId,setClientId]=useState("");
 const[clientSecret,setClientSecret]=useState("");
 const[redirectUri,setRedirectUri]=useState("http://127.0.0.1:17866/api/oauth/callback");
 const[busy,setBusy]=useState("");
 useEffect(()=>{if(!platformId&&platforms[0])setPlatformId(platforms[0].id)},[platformId,platforms]);
 const hasPendingLogin=db.publish_accounts.some(account=>account.integration_type==="browser"&&account.login_status==="login_pending");
 useEffect(()=>{if(!hasPendingLogin)return;const timer=setInterval(()=>refresh(false),1500);return()=>clearInterval(timer)},[hasPendingLogin]);
 const selected=platforms.find(p=>p.id===Number(platformId));
 const statusText={not_logged_in:"未登录",login_pending:"等待登录",login_required:"需要登录",logged_in:"已登录",check_failed:"检测失败"};
 const authText={not_authorized:"未授权",authorizing:"授权中",authorized:"已授权",expired:"已过期"};
 const capabilityText={not_implemented:"未实现",untested:"待测试",testing:"测试中",passed:"已验证",failed:"测试失败",limited:"部分可用"};
 const importGoogle=async()=>{try{const result=await request("/api/select-google-oauth-client",{method:"POST",body:{}});if(!result.client_id)return;setClientId(result.client_id);setClientSecret(result.client_secret);setRedirectUri(result.redirect_uri||redirectUri);notify(`已读取 ${result.source_name}`)}catch(e){notify(e.message)}};
 const add=async()=>{if(!platformId||!accountName.trim())return notify("请选择平台并填写账号名称");if(selected?.code==="youtube"&&(!clientId.trim()||!clientSecret.trim()))return notify("请导入 Google OAuth JSON 或填写 Client ID 和 Client Secret");try{setBusy("add");await request("/api/publish/accounts",{method:"POST",body:{platform_id:Number(platformId),account_name:accountName.trim(),oauth_client_id:clientId.trim(),oauth_client_secret:clientSecret.trim(),oauth_redirect_uri:redirectUri.trim()}});setAccountName("");setClientId("");setClientSecret("");notify("账号接入环境已创建，请点击 OAuth 授权");await refresh()}catch(e){notify(e.message)}finally{setBusy("")}};
 const action=async(account,kind)=>{try{setBusy(`${account.id}-${kind}`);const result=await request(`/api/publish/accounts/${account.id}/${kind}`,{method:"POST",body:{}});if(kind==="login")notify(result.message||result.network_requirement||(account.integration_type==="api"?"已打开 OAuth 授权页":"已打开 Playwright 登录窗口"));else if(kind==="check")notify(result.message||"检测完成");else notify("浏览器目录已打开");await refresh(false)}catch(e){notify(e.message)}finally{setBusy("")}};
 const remove=async account=>{if(!confirm(`确定移除账号“${account.account_name}”？浏览器登录目录会保留。`))return;await request(`/api/publish/accounts/${account.id}`,{method:"DELETE"});notify("账号已移除，登录目录已保留");refresh()};
 const connectedAccounts=db.publish_accounts.filter(account=>account.login_status==="logged_in"||account.authorization_status==="authorized").length;
 return <div className="page publish-account-page account-access-workspace">
  <PageHeader kicker="" title="账号管理" desc="集中管理平台接入方式、登录环境与授权状态。"><Button quiet onClick={onTasks}>返回发布任务</Button>{db.admin_mode&&<Button quiet onClick={onTests}>发布测试</Button>}</PageHeader>

  <section className="account-status-strip" aria-label="账号接入概览">
   <div><Icon name="grid" size={17}/><span>已启用平台<small>国内 {platforms.filter(p=>p.region==="domestic").length} · 海外 {platforms.filter(p=>p.region==="overseas").length}</small></span><strong>{platforms.length}</strong></div>
   <div><Icon name="user" size={17}/><span>账号环境<small>浏览器与 OAuth 独立管理</small></span><strong>{db.publish_accounts.length}</strong></div>
   <div><Icon name="check" size={17}/><span>已连接账号<small>登录或授权状态有效</small></span><strong>{connectedAccounts}</strong></div>
  </section>

  <section className="account-connect-panel">
   <div className="account-section-heading"><div><h2>{selected?.code==="youtube"?"添加 YouTube 账号":"新增平台账号"}</h2><p>{selected?.integration_type==="api"?"使用 OAuth 授权，不保存平台账号密码。":"使用独立浏览器环境保存登录状态。"}</p></div><span>{selected?.integration_type==="api"?"API 接入":"浏览器接入"}</span></div>
   <div className="account-connect-toolbar">
    <label><span>平台</span><select value={platformId} onChange={e=>setPlatformId(Number(e.target.value))}>{platforms.map(p=><option key={p.id} value={p.id}>{p.name} · {p.integration_type==="api"?"API":"浏览器"}</option>)}</select></label>
    <label className="account-name-field"><span>账号名称</span><input value={accountName} onChange={e=>setAccountName(e.target.value)} placeholder="例如：品牌主账号" onKeyDown={e=>e.key==="Enter"&&add()}/></label>
    <Button primary disabled={busy==="add"} onClick={add}>{busy==="add"?"创建中":"创建账号环境"}</Button>
   </div>
   {selected?.integration_type==="api"&&<div className="oauth-compact-row"><label><span>Client ID</span><input value={clientId} onChange={e=>setClientId(e.target.value)} placeholder="OAuth Client ID"/></label><label><span>Client Secret</span><input type="password" value={clientSecret} onChange={e=>setClientSecret(e.target.value)} placeholder="OAuth Client Secret"/></label><label><span>回调地址</span><input value={redirectUri} onChange={e=>setRedirectUri(e.target.value)}/></label>{selected?.code==="youtube"&&<Button quiet onClick={importGoogle}>导入 OAuth 配置</Button>}</div>}
   {selected?.network_requirement&&<div className="account-network-note"><Icon name="bell" size={15}/><span><b>{selected.network_requirement}</b>　授权和状态检测前请确认当前网络可访问该平台。</span></div>}
  </section>

  <section className="platform-adapter-panel">
   <div className="account-section-heading"><div><h2>平台接入</h2><p>选择平台后，可在上方创建对应的账号环境。</p></div><span>{platforms.length} 个平台</span></div>
   <div className="platform-adapter-grid">{platforms.map(p=><button key={p.id} onClick={()=>setPlatformId(p.id)} className={Number(platformId)===p.id?"active":""}>
    <i><Icon name={p.integration_type==="api"?"send":"film"} size={16}/></i>
    <span><b>{p.name}</b><small>{p.integration_type==="api"?"OAuth API 接入":"独立浏览器环境"}</small></span>
    <div><em>{p.network_requirement?"需海外网络":"当前网络"}</em><u className={p.capability_status}>{capabilityText[p.capability_status]||p.capability_status}</u></div>
   </button>)}</div>
  </section>

  <section className="account-resource-panel">
   <div className="account-section-heading"><div><h2>账号授权</h2><p>查看账号状态、登录方式和最近检测结果。</p></div><span>{db.publish_accounts.length} 个账号</span></div>
   <div className="account-resource-table">
    {db.publish_accounts.length>0&&<div className="account-table-head"><span>平台与账号</span><span>接入方式</span><span>当前状态</span><span>最后检测</span><span>操作</span></div>}
    {db.publish_accounts.map(account=><article key={account.id}>
     <div className="account-identity"><i><Icon name={account.integration_type==="api"?"send":"user"} size={16}/></i><span><b>{account.channel_title||account.account_name}</b><small>{account.platform_name}{account.channel_id?` · ${account.channel_id}`:""}</small></span></div>
     <div className="account-method"><b>{account.integration_type==="api"?"OAuth API":"浏览器环境"}</b><small>{account.region==="overseas"?"海外平台":"国内平台"}</small></div>
     <div className="account-state"><i className={account.integration_type==="api"?account.authorization_status:account.login_status}/><span>{account.integration_type==="api"?(authText[account.authorization_status]||account.authorization_status):(statusText[account.login_status]||account.login_status)}<small>{capabilityText[account.capability_status]||account.capability_status}</small></span></div>
     <div className="account-last-check"><b>{account.last_checked_at||"尚未检测"}</b>{account.last_error&&<small title={account.last_error}>{account.last_error}</small>}</div>
     <div className="account-row-actions"><Button quiet disabled={busy===`${account.id}-login`} onClick={()=>action(account,"login")}>{account.integration_type==="api"?(account.authorization_status==="authorized"?"重新授权":"授权"):(account.login_status==="logged_in"?"重新打开":"登录")}</Button><Button quiet disabled={busy===`${account.id}-check`} onClick={()=>action(account,"check")}>检测</Button>{account.integration_type==="browser"&&<button title="打开浏览器目录" onClick={()=>action(account,"open-profile")}><Icon name="folder" size={15}/></button>}<button className="danger" title="移除账号" onClick={()=>remove(account)}><Icon name="trash" size={15}/></button></div>
    </article>)}
    {db.publish_accounts.length===0&&<div className="account-resource-empty"><Icon name="user" size={22}/><div><b>暂无账号环境</b><span>先在上方选择平台并创建账号，随后完成登录或 OAuth 授权。</span></div></div>}
   </div>
  </section>
 </div>
}

function App(){const[page,setPage]=useState(()=>location.pathname.startsWith("/settings")?"\u7cfb\u7edf\u8bbe\u7f6e":"\u5de5\u4f5c\u53f0");const[db,setDb]=useState(empty);const[loading,setLoading]=useState(true);const[message,setMessage]=useState("");const refresh=async(show=true)=>{try{if(show)setLoading(true);const d=await request("/api/bootstrap");setDb(d)}catch(e){setMessage(e.message)}finally{setLoading(false)}};useEffect(()=>{refresh();const timer=setInterval(()=>{if(["\u4efb\u52a1\u4e2d\u5fc3","\u6279\u91cf\u751f\u6210","\u53d1\u5e03\u4e2d\u5fc3"].includes(page))refresh(false)},2500);return()=>clearInterval(timer)},[page]);useEffect(()=>{document.querySelector(".workspace")?.scrollTo({top:0,left:0,behavior:"instant"})},[page]);const notify=m=>{setMessage(m);setTimeout(()=>setMessage(""),3500)};let content=page==="\u5de5\u4f5c\u53f0"?<Workbench db={db} setPage={setPage} refresh={refresh} notify={notify} Button={Button} Icon={Icon}/>:page==="\u8d26\u53f7\u6863\u6848"?<AccountPage db={db} refresh={refresh} notify={notify} Button={Button} Icon={Icon}/>:page==="\u7d20\u6750\u4e2d\u5fc3"?<AssetsPage db={db} refresh={refresh} notify={notify}/>:page==="\u955c\u5934\u526a\u8f91"?<Editor db={db} refresh={refresh} setPage={setPage} notify={notify}/>:page==="\u65f6\u95f4\u8f74"?<TimelinePage db={db} refresh={refresh} notify={notify} Button={Button} Icon={Icon} request={request}/>:page==="\u6279\u91cf\u751f\u6210"?<BatchPage db={db} refresh={refresh} setPage={setPage} notify={notify}/>:page==="\u4efb\u52a1\u4e2d\u5fc3"?<TasksPage db={db} refresh={refresh} notify={notify}/>:page==="\u53d1\u5e03\u4e2d\u5fc3"?<PublishCenter db={db} refresh={refresh} notify={notify}/>:<SettingsPage db={db} refresh={refresh} notify={notify}/>;return <div className="app studio-ui"><Rail page={page} setPage={setPage} tasks={db.tasks.filter(t=>t.status!=="completed").length+db.batch_tasks.filter(b=>["pending","running"].includes(b.status)).length}/><div className="app-main"><Topbar db={db}/><div className="workspace">{loading&&<div className="global-loading">Loading database...</div>}{message&&<div className="global-toast">{message}</div>}{content}</div></div></div>}
createRoot(document.getElementById("root")).render(<App/>);



